theorem ordinalBlockReciprocal_norm_le (b : ∀ i, C(L i, 𝕜)) {γ : ℝ}
    (hγ : 0 < γ) (hb : ∀ i x, γ ≤ ‖b i x‖) (i : I) :
    ‖ordinalBlockReciprocal b (fun i x => norm_pos_iff.mp (hγ.trans_le (hb i x))) i‖ ≤ 1 / γ
